}

.menu ul {
  margin: 0;
  padding: 0;
}

.main ul li {
  float: left;
  border-right: 1px solid #ddd;
  list-style: none;
}

.main ul li a {
  display: block;
  color: #000;
  padding: 10px 20px;
  text-decoration: none;
}

.main ul li a:hover {
  background: #e6b29a;
}

